export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

const eventTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const property = ast.propertySignatures.find((property) => property.name === "_tag")
      return property?.type._tag === "Literal" && typeof property.type.literal === "string"
        ? property.type.literal
        : undefined
    }
    case "Transformation":
      return eventTag(ast.to)
    case "Suspend":
      return eventTag(ast.f())
  }
  return undefined
}

const unionTags = (ast: AST.AST): ReadonlyArray<string> | undefined => {
  const target = ast._tag === "Transformation" ? ast.to : ast._tag === "Suspend" ? ast.f() : ast
  if (target._tag !== "Union") return undefined
  const tags = target.types.map(eventTag)
  return tags.every((tag): tag is string => tag !== undefined) ? tags : undefined
}

