export const makeEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = Schema.encodeUnknown(schema)
  return (value: A): Effect.Effect<string, Schema.Schema.Encoded<ReturnType<typeof encode>>, R> =>
    Effect.map(encode(value), formatDataMessage) as any
}

/**
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = makeEventEncoder(schema)
  const tags = unionTags(schema.ast)
  if (tags === undefined) return encode
  const encodeValue = Schema.encodeUnknown(schema)
